// RE parity scenarios: timesheets.ts, payroll.ts, reports.ts, operations.ts — every write route with valid and invalid
// bodies, allowed and denied users, plus the reads whose state they change. Called from parity.ts moduleScenarios()
// with its helpers (both = same call on the mock and the API; sides = side-specific path/body for ids generated by
// each side). Dates are relative to today (the demo seed is).
/* eslint-disable @typescript-eslint/no-explicit-any */
import { addDays, monthOf, todayISO, weekStart } from '@/domain/calendar'

type Res = { status: number; data?: any; warnings?: unknown; error?: { code: string; message: string; field?: string } }
type Pair = { m: Res; h: Res }
export interface ReHelpers {
  both: (label: string, who: string, method: string, path: string, body?: unknown, query?: Record<string, unknown>, ifMatch?: number) => Promise<Pair>
  sides: (label: string, who: string, method: string, path: (s: 'm' | 'h') => string, body: (s: 'm' | 'h') => unknown) => Promise<Pair | null>
  login: (who: string, email: string) => Promise<void>
  has: (who: string) => boolean
}

const pick = (r: Pair | null, f: (d: any) => any) => (s: 'm' | 'h'): string => {
  const d = r ? (r[s] as Res).data : undefined
  return (d !== undefined && d !== null ? f(d) : undefined) ?? 'x'
}

export async function reScenarios(H: ReHelpers) {
  for (const who of ['subhankar', 'debasish', 'baishali', 'subham', 'jagannath', 'bijaya', 'jayashree', 'pragyasmita', 'rakesh', 'meera', 'sneha'])
    if (!H.has(who)) await H.login(who, ['rakesh', 'meera', 'sneha'].includes(who) ? `${who}@kalingasoft.in` : `${who}@seereon.co.in`)
  await reTimesheets(H)
  await reLeaveDaily(H)
  await rePayroll(H)
  await reOps(H)
  await reReports(H)
}

/* ---------------------------------------------------------------- timesheets ---------------------------------------------------------------- */
async function reTimesheets(H: ReHelpers) {
  const L = 're-ts'
  const { both } = H
  const T = todayISO()
  const W0 = weekStart(T)
  const W1 = addDays(W0, -7)
  const W2 = addDays(W0, -14)
  const days0 = [0, 1, 2, 3, 4, 5, 6].map((i) => addDays(W0, i)).filter((d) => d <= T)
  // reads by many people (lazy locks)
  for (const who of ['santosh', 'subhankar', 'hritesh', 'priya', 'debasish', 'baishali', 'jagannath', 'ananya']) {
    for (const w of [W0, W1, W2, addDays(W0, 7), addDays(W0, 1), 'abc']) await both(L, who, 'GET', `/timesheets/${w}`)
    await both(L, who, 'GET', '/timesheet/work-items')
    await both(L, who, 'GET', '/timesheet/work-items', undefined, { week: W1 })
    await both(L, who, 'GET', '/approvals')
    await both(L, who, 'GET', '/approvals/summary')
    await both(L, who, 'GET', '/approvals/team', undefined, { weeks: 6 })
    await both(L, who, 'GET', '/team/grid')
  }
  for (const [who, u] of [['subhankar', 'u_hritesh'], ['baishali', 'u_hritesh'], ['hritesh', 'u_santosh'], ['santosh', 'u_nope'], ['priya', 'u_bijaya']] as const) await both(L, who, 'GET', `/timesheets/${W1}`, undefined, { user: u })
  // save rules
  const put = (who: string, rows: unknown, ifMatch?: number) => both(L, who, 'PUT', `/timesheets/${W0}`, { rows }, undefined, ifMatch)
  await put('hritesh', 'x')
  await put('hritesh', [{ kind: 'nope' }])
  await put('hritesh', [{ kind: 'task', task_id: 't_missing', hours: { [W0]: 2 } }])
  await put('hritesh', [{ kind: 'task', task_id: 't_hrms_1', hours: { [W0]: 2 } }])
  await put('hritesh', [{ kind: 'internal', internal_code: 'learning', hours: { [W0]: 2 } }])
  await put('hritesh', [{ kind: 'leave', leave_type: 'nope', hours: { [W0]: 9 } }])
  await put('hritesh', [{ kind: 'task', task_id: 't_hrms_5', hours: { [addDays(W0, 7)]: 2 } }])
  await put('hritesh', [{ kind: 'task', task_id: 't_hrms_5', hours: { [W0]: 25 } }])
  await put('hritesh', [{ kind: 'task', task_id: 't_hrms_5', hours: { [W0]: 2.3 } }])
  await put('hritesh', [{ kind: 'task', task_id: 't_hrms_5', hours: { [W0]: 12 } }, { kind: 'task', task_id: 't_mgs_5', hours: { [W0]: 6 } }])
  await put('hritesh', [{ kind: 'task', task_id: 't_hrms_5', hours: { [W0]: 2 } }, { kind: 'task', task_id: 't_hrms_5', hours: { [W0]: 1 } }])
  await put('hritesh', [{ kind: 'leave', leave_type: 'casual', hours: { [addDays(W0, 6)]: 9 } }])
  const hours: Record<string, number> = {}
  days0.forEach((d, i) => (hours[d] = i % 2 ? 7.5 : 9))
  const ok = await put('hritesh', [
    { kind: 'task', task_id: 't_hrms_5', hours },
    { kind: 'internal', internal_code: 'meeting', note: 'Sprint planning', project_id: 'p_hrms', hours: { [W0]: 1 } },
    { kind: 'internal', internal_code: 'breaks', hours: { [W0]: 0.5 } },
    { kind: 'task', task_id: 't_mgs_5', hours: {} },
  ])
  await put('hritesh', [{ kind: 'task', task_id: 't_hrms_5', hours }], ((ok.m.data as any)?.version ?? 1) - 1)
  await both(L, 'hritesh', 'POST', `/timesheets/${W0}/copy-previous`)
  await both(L, 'hritesh', 'POST', `/timesheets/${W0}/copy-previous`, { with_hours: true })
  await both(L, 'hritesh', 'GET', `/timesheets/${W0}`)
  await both(L, 'hritesh', 'POST', `/timesheets/${addDays(W0, 7)}/submit`)
  await both(L, 'bijaya', 'POST', `/timesheets/${W0}/submit`, { rows: [] })
  await both(L, 'hritesh', 'POST', `/timesheets/${W0}/submit`)
  await both(L, 'hritesh', 'POST', `/timesheets/${W0}/submit`)
  await both(L, 'santosh', 'POST', `/timesheets/${W0}/submit`, { rows: [{ kind: 'internal', internal_code: 'admin', note: 'Board prep', hours: { [W0]: 9 } }] })
  await both(L, 'subham', 'POST', `/timesheets/${W1}/submit`)
  // unlock requests
  await both(L, 'jayashree', 'POST', `/timesheets/${W1}/unlock-request`, { reason: 'abc' })
  await both(L, 'jayashree', 'POST', `/timesheets/${W1}/unlock-request`, { reason: 'I was on a client site all week' })
  await both(L, 'jayashree', 'POST', `/timesheets/${W0}/unlock-request`, { reason: 'Need to fix it' })
  // approvals
  await both(L, 'subhankar', 'GET', '/approvals')
  await both(L, 'hritesh', 'POST', `/approvals/wk_hritesh_${W0}/approve`)
  await both(L, 'baishali', 'POST', `/approvals/wk_hritesh_${W0}/approve`)
  await both(L, 'subhankar', 'POST', `/approvals/wk_hritesh_${W0}/approve`, undefined, undefined, 99)
  await both(L, 'subhankar', 'POST', `/approvals/wk_hritesh_${W0}/approve`)
  await both(L, 'subhankar', 'POST', `/approvals/wk_hritesh_${W0}/approve`)
  await both(L, 'subhankar', 'POST', `/approvals/wk_hritesh_${W1}/reject`, { reason: 'no' })
  await both(L, 'subhankar', 'POST', `/approvals/wk_hritesh_${W1}/reject`, { reason: 'Please split the hours by task' })
  await both(L, 'subhankar', 'POST', `/approvals/wk_nope/approve`)
  await both(L, 'subhankar', 'POST', '/approvals/bulk-approve', {})
  await both(L, 'santosh', 'POST', '/approvals/bulk-approve', { ids: [`wk_baishali_${W1}`, 'wk_nope', `wk_santosh_${W0}`, `wk_pragyasmita_${W2}`, `wk_bijaya_${W1}`] })
  await both(L, 'subhankar', 'POST', '/approvals/bulk-approve', { ids: [`wk_bijaya_${W1}`, `wk_pragyasmita_${W2}`] })
  // unlock / deny / unlock-week
  await both(L, 'subhankar', 'POST', `/approvals/wk_jayashree_${W1}/unlock`, { days: 0 })
  await both(L, 'subhankar', 'POST', `/approvals/wk_jayashree_${W1}/unlock`, { days: 3 })
  await both(L, 'subhankar', 'POST', `/approvals/wk_pragyasmita_${W1}/unlock`, { days: 2 })
  await both(L, 'subhankar', 'POST', `/approvals/wk_pragyasmita_${W1}/unlock`, { days: 2, reason: 'Reopening so you can log the visit' })
  await both(L, 'subhankar', 'POST', `/approvals/wk_jagannath_${W1}/deny-unlock`, { reason: 'no' })
  await both(L, 'subhankar', 'POST', `/approvals/wk_jagannath_${W1}/deny-unlock`, { reason: 'The week is already in payroll' })
  await both(L, 'subhankar', 'POST', `/approvals/wk_jagannath_${W1}/deny-unlock`, { reason: 'The week is already in payroll' })
  const old = addDays(W0, -20 * 7)
  await both(L, 'subhankar', 'POST', '/approvals/unlock-week', {})
  await both(L, 'subhankar', 'POST', '/approvals/unlock-week', { user_id: 'u_hritesh', week_start: W0 })
  await both(L, 'subhankar', 'POST', '/approvals/unlock-week', { user_id: 'u_subhankar', week_start: old })
  await both(L, 'subhankar', 'POST', '/approvals/unlock-week', { user_id: 'u_hritesh', week_start: old, days: 5 })
  await both(L, 'subhankar', 'POST', '/approvals/unlock-week', { user_id: 'u_hritesh', week_start: old, days: 5, reason: 'Back-filling for the audit' })
  for (const who of ['subhankar', 'santosh', 'hritesh', 'jayashree']) {
    await both(L, who, 'GET', '/approvals')
    await both(L, who, 'GET', '/approvals/team')
    await both(L, who, 'GET', `/timesheets/${W1}`)
  }
  await both(L, 'santosh', 'GET', '/team/grid', undefined, { weeks: 12 })
}

/* ---------------------------------------------------------------- leave + daily ---------------------------------------------------------------- */
async function reLeaveDaily(H: ReHelpers) {
  const L = 're-leave'
  const { both, sides } = H
  const T = todayISO()
  const W0 = weekStart(T)
  const next = addDays(W0, 14)
  await both(L, 'hritesh', 'POST', '/leave', {})
  await both(L, 'hritesh', 'POST', '/leave', { type: 'casual', from: addDays(next, 2), to: addDays(next, 1) })
  await both(L, 'hritesh', 'POST', '/leave', { type: 'casual', portion: 'half', from: next, to: addDays(next, 1) })
  await both(L, 'hritesh', 'POST', '/leave', { type: 'casual', from: addDays(next, 6) })
  await both(L, 'hritesh', 'POST', '/leave', { user_id: 'u_bijaya', type: 'casual', from: next })
  await both(L, 'hritesh', 'POST', '/leave', { type: 'optional_holiday', from: next })
  await both(L, 'hritesh', 'POST', '/leave', { type: 'casual', from: next, to: addDays(next, 6) })
  await both(L, 'hritesh', 'POST', '/leave', { type: 'casual', from: next, to: addDays(next, 6) })
  await both(L, 'hritesh', 'POST', '/leave', { type: 'sick', portion: 'half', from: addDays(next, 8) })
  await both(L, 'priya', 'POST', '/leave', { user_id: 'u_bijaya', type: 'earned', from: addDays(next, 14), to: addDays(next, 16) })
  await both(L, 'priya', 'POST', '/leave', { user_id: 'u_nope', type: 'earned', from: addDays(next, 14) })
  const lv = await both(L, 'hritesh', 'GET', '/leave')
  const mine = ((lv.m.data as any)?.items ?? []) as { id: string; date: string; user_id: string }[]
  const idx = mine.findIndex((x) => x.date >= next)
  if (idx >= 0) {
    const pickId = (s: 'm' | 'h') => (((lv[s] as Res).data as any)?.items ?? [])[idx]?.id ?? 'x'
    await sides(L, 'bijaya', 'DELETE', (s) => `/leave/${pickId(s)}`, () => undefined)
    await sides(L, 'hritesh', 'DELETE', (s) => `/leave/${pickId(s)}`, () => undefined)
    await sides(L, 'hritesh', 'DELETE', (s) => `/leave/${pickId(s)}`, () => undefined)
  }
  for (const who of ['hritesh', 'priya', 'subhankar', 'santosh']) {
    for (const scope of ['mine', 'team', 'all']) await both(L, who, 'GET', '/leave', undefined, { scope })
    await both(L, who, 'GET', '/leave/summary')
    await both(L, who, 'GET', `/timesheets/${next}`)
  }
  await both(L, 'santosh', 'GET', '/holidays-lite')
  // daily updates
  const D = 're-daily'
  for (const body of [{}, { done: 'tiny' }, { done: 'Finished the payslip exporter', date: '2099-01-01' }, { done: 'Finished the payslip exporter' },
    { done: 'Finished the payslip exporter', proof_url: 'ftp://x' }, { done: 'Finished the payslip exporter', proof_url: 'https://git.example.com/c/1', blocker: 'Waiting for HR' },
    { done: 'Finished the payslip exporter v2', proof_url: 'https://git.example.com/c/2', demo_shown: true }])
    await both(D, 'hritesh', 'POST', '/daily', body)
  for (const body of [{}, { demo_shown: true }, { demo_shown: true, demo_note: 'tiny' }, { demo_shown: true, demo_note: 'Demoed the leave approval flow' }, { date: addDays(W0, -7) }])
    await both(D, 'hritesh', 'POST', '/daily/demo', body)
  for (const who of ['hritesh', 'subhankar', 'santosh']) await both(D, who, 'GET', '/daily')
  await both(D, 'santosh', 'GET', '/daily', undefined, { date: addDays(T, -1) })
}

/* ---------------------------------------------------------------- payroll ---------------------------------------------------------------- */
async function rePayroll(H: ReHelpers) {
  const L = 're-payroll'
  const { both, sides } = H
  const T = todayISO()
  const ym = monthOf(T)
  const prev = monthOf(addDays(`${ym}-01`, -1))
  await both(L, 'hritesh', 'GET', '/payroll')
  const list = await both(L, 'santosh', 'GET', '/payroll')
  const runs = (Array.isArray(list.m.data) ? list.m.data : []) as { id: string; month: string; status: string }[]
  for (const r of runs) await both(L, 'santosh', 'GET', `/payroll/${r.id}`)
  await both(L, 'santosh', 'GET', '/payroll/nope')
  for (const body of [{}, { month: '2026-13' }, { month: '2099-01' }]) await both(L, 'santosh', 'POST', '/payroll/run', body)
  const fin = runs.find((r) => r.status === 'final')
  if (fin) await both(L, 'santosh', 'POST', '/payroll/run', { month: fin.month })
  await both(L, 'hritesh', 'POST', '/payroll/run', { month: prev })
  const run = await both(L, 'santosh', 'POST', '/payroll/run', { month: prev })
  await both(L, 'santosh', 'POST', '/payroll/run', { month: ym })
  const rid = pick(run, (d) => d.run?.id)
  await sides(L, 'santosh', 'POST', (s) => `/payroll/${rid(s)}/recompute`, () => undefined)
  if (fin) await both(L, 'santosh', 'POST', `/payroll/${fin.id}/recompute`)
  await sides(L, 'hritesh', 'POST', (s) => `/payroll/${rid(s)}/finalise`, () => undefined)
  const f = await sides(L, 'santosh', 'POST', (s) => `/payroll/${rid(s)}/finalise`, () => undefined)
  await sides(L, 'santosh', 'POST', (s) => `/payroll/${rid(s)}/recompute`, () => undefined)
  await both(L, 'santosh', 'POST', '/payroll/run', { month: prev })
  await both(L, 'santosh', 'GET', '/payroll')
  const cs = pick(f, (d) => d.change?.id)
  await sides(L, 'santosh', 'POST', (s) => `/changes/${cs(s)}/approve`, () => ({}))
  await sides(L, 'debasish', 'POST', (s) => `/changes/${cs(s)}/approve`, () => ({ note: 'Checked' }))
  await sides(L, 'santosh', 'GET', (s) => `/payroll/${rid(s)}`, () => undefined)
  await sides(L, 'santosh', 'POST', (s) => `/payroll/${rid(s)}/finalise`, () => undefined)
  await both(L, 'santosh', 'GET', '/payroll')
  await both(L, 'santosh', 'GET', '/notifications')
  await both(L, 'hritesh', 'GET', '/notifications')
  // maker-checker off (Kalinga): direct finalisation
  const k = await both(L, 'ananya', 'POST', '/payroll/run', { month: prev })
  const kid = pick(k, (d) => d.run?.id)
  await sides(L, 'ananya', 'POST', (s) => `/payroll/${kid(s)}/finalise`, () => undefined)
  await sides(L, 'ananya', 'POST', (s) => `/payroll/${kid(s)}/finalise`, () => undefined)
  await sides(L, 'ananya', 'GET', (s) => `/payroll/${kid(s)}`, () => undefined)
  await both(L, 'ananya', 'GET', '/payroll')
}

/* ---------------------------------------------------------------- operations ---------------------------------------------------------------- */
async function reOps(H: ReHelpers) {
  const L = 're-ops'
  const { both, sides } = H
  const T = todayISO()
  for (const who of ['santosh', 'priya', 'hritesh', 'debasish', 'ananya']) {
    await both(L, who, 'GET', '/ops')
    await both(L, who, 'GET', '/ops', undefined, { owner_id: 'u_priya', q: 'gst' })
    await both(L, who, 'GET', '/ops/summary')
  }
  for (const body of [{}, { item: 'ab' }, { item: 'TDS return', category: 'tax' }, { item: 'TDS return', category: 'compliance', recurring: 'daily' },
    { item: 'TDS return', category: 'compliance', recurring: 'quarterly', due_on: 'bad' }, { item: 'TDS return', category: 'compliance', recurring: 'quarterly', due_on: T, owner_id: 'u_ankit' }])
    await both(L, 'priya', 'POST', '/ops', body)
  await both(L, 'hritesh', 'POST', '/ops', { item: 'Nope', category: 'it', recurring: 'none', due_on: T, owner_id: 'u_hritesh' })
  const w = await both(L, 'priya', 'POST', '/ops', { item: '  Weekly backup check ', category: 'it', recurring: 'weekly', due_on: addDays(T, -40), owner_id: 'u_hritesh', notes: ' NAS ' })
  const n = await both(L, 'priya', 'POST', '/ops', { item: 'One-off licence renewal', category: 'admin', recurring: 'none', due_on: addDays(T, -3), owner_id: 'u_priya' })
  const q = await both(L, 'priya', 'POST', '/ops', { item: 'Quarterly GST', category: 'compliance', recurring: 'quarterly', due_on: addDays(T, 5), owner_id: 'u_debasish' })
  for (const r of [w, n, q]) {
    const id = pick(r, (d) => d.id)
    await sides(L, 'hritesh', 'POST', (s) => `/ops/${id(s)}/done`, () => ({}))
    await sides(L, 'priya', 'POST', (s) => `/ops/${id(s)}/done`, () => ({ done_on: '2099-01-01' }))
    await sides(L, 'priya', 'POST', (s) => `/ops/${id(s)}/done`, () => ({ done_on: addDays(T, -1) }))
    await sides(L, 'priya', 'POST', (s) => `/ops/${id(s)}/done`, () => ({}))
  }
  const nid = pick(n, (d) => d.id)
  await sides(L, 'priya', 'PATCH', (s) => `/ops/${nid(s)}`, () => ({ status: 'open', due_on: addDays(T, 30), notes: ' reopened ' }))
  await sides(L, 'priya', 'PATCH', (s) => `/ops/${nid(s)}`, () => ({ owner_id: 'u_nope' }))
  await sides(L, 'hritesh', 'DELETE', (s) => `/ops/${nid(s)}`, () => undefined)
  await sides(L, 'priya', 'DELETE', (s) => `/ops/${nid(s)}`, () => undefined)
  await sides(L, 'priya', 'DELETE', (s) => `/ops/${nid(s)}`, () => undefined)
  await both(L, 'priya', 'GET', '/ops')
  await both(L, 'priya', 'GET', '/ops/summary')
  await both(L, 'hritesh', 'GET', '/notifications')
}

/* ---------------------------------------------------------------- reports + AI ---------------------------------------------------------------- */
async function reReports(H: ReHelpers) {
  const L = 're-reports'
  const { both, sides } = H
  const specs: unknown[] = [
    { dataset: 'projects', measures: [], dimensions: [] },
    { dataset: 'tasks', measures: [{ field: '*', agg: 'count' }], dimensions: [{ field: 'owner' }], compare: 'previous_period', period: { preset: 'this_fy', field: 'due_on' } },
    { dataset: 'hours', measures: [{ field: 'hours', agg: 'sum' }], dimensions: [{ field: 'date', grain: 'week' }], period: { preset: 'last_90_days' } },
    { dataset: 'ledger', measures: [{ field: 'billed', agg: 'sum' }, { field: 'collected', agg: 'sum' }], dimensions: [{ field: 'date', grain: 'month' }], period: { preset: 'last_12_months' } },
    { dataset: 'deals', measures: [{ field: 'value', agg: 'sum' }], dimensions: [{ field: 'stage' }, { field: 'owner' }], filters: [{ field: 'is_open', op: 'eq', value: 'true' }] },
    { dataset: 'people', measures: [], dimensions: [], columns: ['name', 'last_week_status', 'ts_compliance_8w', 'ctc'] },
    { dataset: 'payroll', measures: [{ field: 'net', agg: 'sum' }], dimensions: [{ field: 'month', grain: 'month' }], period: { preset: 'this_fy' } },
    { dataset: 'invoices', measures: [{ field: 'outstanding', agg: 'sum' }], dimensions: [{ field: 'client' }], sort: [{ field: 'sum_outstanding', dir: 'asc' }], limit: 3 },
    { dataset: 'okr_key_results', measures: [], dimensions: [] },
    { dataset: 'documents', measures: [{ field: '*', agg: 'count' }], dimensions: [{ field: 'category' }] },
    { dataset: 'budget_vs_actual', measures: [{ field: 'budget', agg: 'sum' }, { field: 'actual', agg: 'sum' }], dimensions: [{ field: 'category' }] },
    { dataset: 'appraisals', measures: [], dimensions: [] },
    { dataset: 'nope' },
  ]
  for (const who of ['santosh', 'subhankar', 'hritesh', 'baishali', 'priya', 'ananya']) {
    await both(L, who, 'GET', '/reports/datasets')
    await both(L, who, 'GET', '/reports')
    await both(L, who, 'GET', '/ai/context')
    for (const spec of specs) await both(L, who, 'POST', '/reports/run', { spec })
    for (const t of ['project_health', 'pipeline', 'approvals']) await both(L, who, 'GET', `/ai/tools/${t}`)
    await both(L, who, 'GET', '/ai/tools/entities', undefined, { kind: 'clients' })
    for (const q of ['Revenue by stream this FY', 'Who hasn’t submitted last week’s timesheet?', 'overdue tasks by project', 'my hours by week last 8 weeks', 'ab'])
      await both(L, who, 'POST', '/ai/plan', { question: q })
    for (const q of ['Revenue by stream this FY', 'Payroll cost by department this FY', 'Why are tasks delayed?', 'Stale deals'])
      await both(L, who, 'POST', '/ai/answer', { question: q })
  }
  // saved reports CRUD
  const spec = { dataset: 'tasks', measures: [{ field: '*', agg: 'count' }], dimensions: [{ field: 'owner' }], chart: 'bar' }
  await both(L, 'hritesh', 'POST', '/reports', { name: 'x' })
  await both(L, 'hritesh', 'POST', '/reports', { name: 'Ok name', spec: { dataset: 'payroll' } })
  const r = await both(L, 'hritesh', 'POST', '/reports', { name: '  My tasks by owner ', spec, shared: true, schedule: 'weekly' })
  const rid = pick(r, (d) => d.id)
  await sides(L, 'subhankar', 'PATCH', (s) => `/reports/${rid(s)}`, () => ({ name: 'Hijack' }))
  await sides(L, 'hritesh', 'PATCH', (s) => `/reports/${rid(s)}`, () => ({ name: 'By status', spec: { ...spec, dimensions: [{ field: 'status' }] } }))
  await sides(L, 'hritesh', 'POST', (s) => `/reports/${rid(s)}/pin`, () => ({}))
  await sides(L, 'hritesh', 'POST', (s) => `/reports/${rid(s)}/share`, () => ({ shared: false }))
  await sides(L, 'hritesh', 'POST', (s) => `/reports/${rid(s)}/run`, () => ({ period: { preset: 'this_month' } }))
  await sides(L, 'hritesh', 'GET', (s) => `/reports/${rid(s)}`, () => undefined)
  await sides(L, 'santosh', 'POST', (s) => `/reports/${rid(s)}/duplicate`, () => ({}))
  await sides(L, 'subhankar', 'DELETE', (s) => `/reports/${rid(s)}`, () => undefined)
  await sides(L, 'hritesh', 'DELETE', (s) => `/reports/${rid(s)}`, () => undefined)
  const all = await both(L, 'santosh', 'GET', '/reports', undefined, { preview: '0' })
  const first = (Array.isArray(all.m.data) ? (all.m.data as any[]) : [])[0]?.id
  if (first) {
    await both(L, 'subhankar', 'DELETE', `/reports/${first}`)
    await both(L, 'santosh', 'POST', `/reports/${first}/run`)
    await both(L, 'santosh', 'GET', `/reports/${first}`)
  }
  await both(L, 'santosh', 'GET', '/reports')
}
